// VX60-SEC M1 — KAT gate for the Duplex Sponge AEAD (whitebook §4.5).
//
// The vectors are GENERATED by scripts/gen_vx60_aead_kat.py — a pure-Python
// Keccak oracle whose core is self-checked against hashlib.sha3_256 at
// generation time. This test pins the C++ implementation to those vectors
// bit-for-bit (checklist 2: no KAT, no ship) and pins the RUP invariant:
// a failed tag MUST zero the plaintext before the false return.
#include <gtest/gtest.h>

#include "vx/net/vx60_aead.hpp"

#include "vx60_aead_kat_vectors.hpp" // generated: scripts/gen_vx60_aead_kat.py

#include <cstring>
#include <string>
#include <vector>

namespace {

const std::vector<vx::net::vx60_test::KatVector> &kats() {
    static const auto v = vx::net::vx60_test::kat_vectors();
    return v;
}

} // namespace

// Seal must reproduce the oracle's ciphertext AND tag bit-for-bit, for
// every generated vector — including the pad-boundary pins (merged pad
// 0x81, full-pad-block) and the 64 KiB frame-size vector.
TEST(Vx60AeadKat, SealMatchesOracleBitForBit) {
    for (const auto &v : kats()) {
        std::vector<uint8_t> work(v.pt.begin(), v.pt.end());
        std::array<uint8_t, vx::net::vx60::kAeadTagSize> tag{};
        vx::net::vx60::aead_seal(v.key.data(), v.nonce.data(), v.ad.empty() ? nullptr : v.ad.data(),
                                 v.ad.size(), work.data(), work.size(), tag.data());
        EXPECT_EQ(work, v.ct) << "ciphertext mismatch: " << v.name;
        EXPECT_EQ(std::vector<uint8_t>(tag.begin(), tag.end()), v.tag)
            << "tag mismatch: " << v.name;
    }
}

// Open(recognized tag) returns the plaintext exactly.
TEST(Vx60AeadKat, OpenRoundTripsEveryVector) {
    for (const auto &v : kats()) {
        std::vector<uint8_t> work(v.ct.begin(), v.ct.end());
        EXPECT_TRUE(vx::net::vx60::aead_open(v.key.data(), v.nonce.data(),
                                             v.ad.empty() ? nullptr : v.ad.data(), v.ad.size(),
                                             work.data(), work.size(), v.tag.data()))
            << "open failed: " << v.name;
        EXPECT_EQ(work, v.pt) << "plaintext mismatch: " << v.name;
    }
}

// RUP invariant: ONE flipped tag bit → open refuses AND zeroes the
// plaintext buffer before returning false. Zero plaintext stays zero —
// a caller can never observe unverified bytes either way.
TEST(Vx60AeadKat, TagFailureZeroesPlaintextBeforeRefusal) {
    for (const auto &v : kats()) {
        std::vector<uint8_t> work(v.ct.begin(), v.ct.end());
        std::vector<uint8_t> before = work;
        auto tag = v.tag;
        tag[0] ^= 0x01; // single-bit flip: the strongest tag corruption
        EXPECT_FALSE(vx::net::vx60::aead_open(v.key.data(), v.nonce.data(),
                                              v.ad.empty() ? nullptr : v.ad.data(), v.ad.size(),
                                              work.data(), work.size(), tag.data()))
            << "open accepted a corrupted tag: " << v.name;
        EXPECT_EQ(work, std::vector<uint8_t>(work.size(), 0))
            << "unverified plaintext released on tag failure: " << v.name;
        (void)before;
    }
}

// Ciphertext tampering is refused the same way (the duplex absorbs the
// ciphertext, so any body bit moves the tag).
TEST(Vx60AeadKat, CiphertextTamperingRefusedAndZeroed) {
    for (const auto &v : kats()) {
        if (v.ct.empty())
            continue; // nothing to tamper with
        std::vector<uint8_t> work = v.ct;
        work[work.size() / 2] ^= 0x80;
        EXPECT_FALSE(vx::net::vx60::aead_open(v.key.data(), v.nonce.data(),
                                              v.ad.empty() ? nullptr : v.ad.data(), v.ad.size(),
                                              work.data(), work.size(), v.tag.data()))
            << "open accepted a tampered body: " << v.name;
        EXPECT_EQ(work, std::vector<uint8_t>(work.size(), 0))
            << "body tamper leaked plaintext: " << v.name;
    }
}

// AD is authenticated: the same ct under a DIFFERENT ad refuses.
TEST(Vx60AeadKat, AdIsBinding) {
    for (const auto &v : kats()) {
        std::vector<uint8_t> work(v.ct.begin(), v.ct.end());
        std::vector<uint8_t> other_ad = v.ad;
        other_ad.push_back(other_ad.empty() ? 0x42 : static_cast<uint8_t>(other_ad[0] ^ 1));
        EXPECT_FALSE(vx::net::vx60::aead_open(v.key.data(), v.nonce.data(), other_ad.data(),
                                              other_ad.size(), work.data(), work.size(),
                                              v.tag.data()))
            << "AD not binding: " << v.name;
        EXPECT_EQ(work, std::vector<uint8_t>(work.size(), 0));
    }
}
